# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DE SU TÜKETİMİNİN SEKTÖREL DAĞILIMI VE SU VARLIĞI</text>\n  <rect x="20" y="44" width="320" height="184" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Sektörel Su Kullanım Oranları</text>\n  <rect x="38" y="82" width="210" height="28" rx="5" fill="#16a34a"/>\n  <text x="46" y="100" font-size="10" font-weight="bold" fill="#ffffff">Tarımsal Sulama (~%74 - %77)</text>\n  <rect x="38" y="120" width="90" height="28" rx="5" fill="#2563eb"/>\n  <text x="136" y="138" font-size="10" font-weight="bold" fill="#1e40af">İçme ve Kullanma (~%13)</text>\n  <rect x="38" y="158" width="75" height="28" rx="5" fill="#d97706"/>\n  <text x="121" y="176" font-size="10" font-weight="bold" fill="#92400e">Sanayi Üretimi (~%10 - %13)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">En büyük pay tarımsal sulamaya aittir.</text>\n  <rect x="360" y="44" width="320" height="184" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Falkenmark Su Göstergesi ve Türkiye</text>\n  <rect x="376" y="78" width="288" height="134" rx="6" fill="#ffffff" stroke="#fbbf24" stroke-width="1"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" fill="#166534">• &gt; 1.700 m³/kişi-yıl : Su Zengini (Sorun Yok)</text>\n  <text x="520" y="120" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• 1.000 - 1.700 m³ : Su Stresi (Su Sıkıntısı)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="10" fill="#dc2626">• &lt; 1.000 m³/kişi-yıl : Su Fakiri (Kıtlık)</text>\n  <line x1="395" y1="154" x2="645" y2="154" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="520" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Türkiye: ~1.300 m³/kişi-yıl</text>\n  <text x="520" y="194" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">Türkiye \'Su Stresi Yaşayan\' bir ülkedir!</text>\n</svg>', '<svg viewBox="0 0 700 235" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="235" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DEKİ SU KAYNAKLARININ ÇOK BOYUTLU ETKİLERİ</text>\n  <rect x="18" y="44" width="155" height="172" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="95" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">1. EKONOMİK ETKİ</text>\n  <text x="95" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Tarımsal sulama (GAP, KOP)</text>\n  <text x="95" y="110" text-anchor="middle" font-size="9.5" fill="#334155">• Hidroelektrik (HES)</text>\n  <text x="95" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• Jeotermal enerji ve sera</text>\n  <text x="95" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Deniz ticareti ve limanlar</text>\n  <text x="95" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Su ürünleri ve turizm</text>\n  <rect x="187" y="44" width="155" height="172" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="264" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">2. POLİTİK ETKİ</text>\n  <text x="264" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Sınır aşan sular yönetimi</text>\n  <text x="264" y="110" text-anchor="middle" font-size="9.5" fill="#334155">• Fırat ve Dicle havzası</text>\n  <text x="264" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• Çoruh, Aras, Kura, Meriç</text>\n  <text x="264" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Türk Boğazları stratejisi</text>\n  <text x="264" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Hidropolitik güç dengesi</text>\n  <rect x="356" y="44" width="155" height="172" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="433" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">3. SOSYOKÜLTÜREL</text>\n  <text x="433" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Akarsu boyu yerleşmeler</text>\n  <text x="433" y="110" text-anchor="middle" font-size="9.5" fill="#334155">• Hamam ve kaplıca kültürü</text>\n  <text x="433" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• Göçün önlenmesi (GAP)</text>\n  <text x="433" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Baraj havzası iskanları</text>\n  <text x="433" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Rekreatif su sporları</text>\n  <rect x="525" y="44" width="157" height="172" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="603" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">4. ÇEVRESEL ETKİ</text>\n  <text x="603" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Sulak alan biyoçeşitliliği</text>\n  <text x="603" y="110" text-anchor="middle" font-size="9.5" fill="#334155">• Ramsar kuş cennetleri</text>\n  <text x="603" y="130" text-anchor="middle" font-size="9.5" fill="#334155">• Mikroklima etkisi</text>\n  <text x="603" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Kuruma ve obruk riski</text>\n  <text x="603" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Müsilaj ve ötrofikasyon</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SU KAYNAKLARINA YÖNELİK TEHDİTLER VE SÜRDÜRÜLEBİLİR ÇÖZÜMLER</text>\n  <rect x="25" y="46" width="305" height="158" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="177" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">BAŞLICA ÇEVRESEL TEHDİTLER</text>\n  <text x="177" y="94" text-anchor="middle" font-size="10" fill="#334155">• Vahşi (salma) sulama ve aşırı buharlaşma</text>\n  <text x="177" y="114" text-anchor="middle" font-size="10" fill="#334155">• Kontrolsüz yer altı suyu çekimi → Obruklar</text>\n  <text x="177" y="134" text-anchor="middle" font-size="10" fill="#334155">• Göl ve sulak alanların kuruması (Tuz, Burdur)</text>\n  <text x="177" y="154" text-anchor="middle" font-size="10" fill="#334155">• Tarımsal gübre ve atık su → Ötrofikasyon</text>\n  <text x="177" y="174" text-anchor="middle" font-size="10" fill="#334155">• Marmara Denizi\'nde müsilaj (deniz salyası)</text>\n  <line x1="330" y1="125" x2="370" y2="125" stroke="#16a34a" stroke-width="2.5"/>\n  <polygon points="370,125 360,119 360,131" fill="#16a34a"/>\n  <rect x="370" y="46" width="305" height="158" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="522" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">SÜRDÜRÜLEBİLİR SU YÖNETİMİ</text>\n  <text x="522" y="94" text-anchor="middle" font-size="10" fill="#334155">• Damla ve yağmurlama sulamaya geçiş</text>\n  <text x="522" y="114" text-anchor="middle" font-size="10" fill="#334155">• İklime uygun (az su isteyen) ürün deseni</text>\n  <text x="522" y="134" text-anchor="middle" font-size="10" fill="#334155">• İleri biyolojik arıtma ve gri su geri kazanımı</text>\n  <text x="522" y="154" text-anchor="middle" font-size="10" fill="#334155">• Yağmur suyu hasadı ve şebeke kayıp önleme</text>\n  <text x="522" y="174" text-anchor="middle" font-size="10" fill="#334155">• Ramsar Sözleşmesi ile sulak alan koruma</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
